def transform(grid):
    """Tile 8-cells with 2x2 squares and L triominoes; color each tile by type."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    tiles = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            if box <= cells:
                tiles.append((box, 1))
            # The three L orientations used by this task.
            for missing, color in (((r, c), 2), ((r + 1, c), 3), ((r, c + 1), 4)):
                shape = box - {missing}
                if shape <= cells:
                    tiles.append((shape, color))
    by_cell = {p: [] for p in cells}
    for i, (shape, _) in enumerate(tiles):
        for p in shape:
            by_cell[p].append(i)

    # Exact-cover search, choosing the most constrained remaining cell first.
    failed = set()
    def solve(left):
        if not left:
            return ()
        key = frozenset(left)
        if key in failed:
            return None
        p = min(left, key=lambda q: sum(tiles[i][0] <= left for i in by_cell[q]))
        for i in by_cell[p]:
            shape, _ = tiles[i]
            if shape <= left:
                rest = solve(left - shape)
                if rest is not None:
                    return (i,) + rest
        failed.add(key)
        return None

    chosen = solve(cells)
    if chosen is None:
        return [row[:] for row in grid]
    out = [[0] * w for _ in range(h)]
    for i in chosen:
        shape, color = tiles[i]
        for r, c in shape:
            out[r][c] = color
    return out
